package dev.henrique.inventory.api;
import static dev.henrique.inventory.api.ApiModels.*; import dev.henrique.inventory.domain.*; import dev.henrique.inventory.repository.ProductRepository; import dev.henrique.inventory.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class ApiController { private final ProductRepository products;private final InventoryService inventory;private final ReservationService reservations; public ApiController(ProductRepository p,InventoryService i,ReservationService r){products=p;inventory=i;reservations=r;}
 @PostMapping("/products") @ResponseStatus(HttpStatus.CREATED) ProductResponse createProduct(@Valid @RequestBody CreateProductRequest q){return ProductResponse.from(products.save(new Product(q.sku(),q.name())));} @GetMapping("/products") List<ProductResponse> products(){return products.findAll().stream().map(ProductResponse::from).toList();} @GetMapping("/products/{id}") ProductResponse product(@PathVariable UUID id){return ProductResponse.from(products.findById(id).orElseThrow(()->new ResourceNotFoundException("Product not found: "+id)));}
 @PutMapping("/inventory/{id}") InventoryResponse setInventory(@PathVariable UUID id,@Valid @RequestBody SetInventoryRequest q){return InventoryResponse.from(inventory.set(id,q.quantity()));} @GetMapping("/inventory/{id}") InventoryResponse inventory(@PathVariable UUID id){return InventoryResponse.from(inventory.get(id));}
 @PostMapping("/reservations") @ResponseStatus(HttpStatus.CREATED) ReservationResponse reserve(@Valid @RequestBody CreateReservationRequest q){return ReservationResponse.from(reservations.create(q.items()));} @GetMapping("/reservations/{id}") ReservationResponse reservation(@PathVariable UUID id){return ReservationResponse.from(reservations.get(id));} @PostMapping("/reservations/{id}/confirm") ReservationResponse confirm(@PathVariable UUID id){return ReservationResponse.from(reservations.transition(id,ReservationStatus.CONFIRMED));} @PostMapping("/reservations/{id}/cancel") ReservationResponse cancel(@PathVariable UUID id){return ReservationResponse.from(reservations.transition(id,ReservationStatus.CANCELLED));}
}
